#!/usr/bin/env python3
"""Local development environmental state only; never business/native authority."""
import base64,hashlib,json,os,re,stat
from pathlib import Path
SERVICES={'backend','frontend','postgres','inquiry','redis','clamav','backend-candidate','backend-retained','frontend-candidate','frontend-retained'}
def require(value,code):
 if not value:raise RuntimeError('LOCAL_DEV_SUSPENSION_'+code)
def sha(raw):return hashlib.sha256(raw).hexdigest()
def canonical(value):return json.dumps(value,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()
def stable(file,maximum=4*1024*1024):
 file=Path(file);require(file.is_absolute()and file.resolve(strict=True)==file,'PATH');fd=os.open(file,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
 try:
  before=os.fstat(fd);require(stat.S_ISREG(before.st_mode)and before.st_nlink==1 and 0<before.st_size<=maximum,'FILE');raw=os.read(fd,maximum+1);key=lambda s:(s.st_dev,s.st_ino,s.st_size,s.st_mtime_ns,s.st_ctime_ns,s.st_nlink);require(len(raw)==before.st_size and key(before)==key(os.fstat(fd))==key(file.lstat()),'CHANGED');return raw
 finally:os.close(fd)
def native_file(value):
 require(isinstance(value,str),'WINDOWS_PATH');value=value.replace('\\','/');require(re.fullmatch(r'[A-Z]:/[^\\]+',value)and all(x not in ('','.','..')for x in value[3:].split('/')),'WINDOWS_PATH');return Path('/mnt/host')/value[0].lower()/value[3:]
def validate_scope(config,readback=True):
 require('localDevSuspension'in config and config.get('project')=='sabalanerp-local','LOCAL_SCOPE_REQUIRED');scope=config['localDevSuspension'];require(isinstance(scope,dict)and set(scope)=={'format','project','service','selection','receiptSha256','receiptRawBase64','capture','productionAdmission'},'SCHEMA');require(scope['format']=='sabalan-local-dev-capture-suspension/v1'and scope['project']=='sabalanerp-local'and scope['service']=='frontend'and scope['productionAdmission']is False,'SCOPE');require(re.fullmatch(r'qa_application_(?:native|restored)_[a-f0-9]{32}',config['database']['name']),'DATABASE');require(scope['capture']==dict(runtimeId=config['capture']['runtimeId'],scopeSha256=config['capture']['scopeSha256']),'CAPTURE_CHANGED');require(re.fullmatch('[a-f0-9]{64}',scope['capture']['runtimeId'])and re.fullmatch('[a-f0-9]{64}',scope['capture']['scopeSha256']),'CAPTURE_ID');raw=base64.b64decode(scope['receiptRawBase64'],validate=True);require(base64.b64encode(raw).decode()==scope['receiptRawBase64']and sha(raw)==scope['receiptSha256'],'RECEIPT_HASH');selection=scope['selection'];require(set(selection)=={'file','sha256'}and selection['sha256']==scope['receiptSha256'],'SELECTION');v=json.loads(raw);require(v['format']=='sabalan-local-dev-frontend-suspension/v1'and v['project']=='sabalanerp-local'and v['service']=='frontend'and v['composeFile']=='D:/sabalanerp/docker-compose.local.yml','RECEIPT_SCOPE');require(v['productionAdmission']is False and v['nativeClosureClaimed']is False and v['restorationRequired']is True,'NO_AUTHORITY');require(v['composeSha256']==config['composeSha256']and v['ownerSourceSha256']==config['helpers']['suspensionOwner']['sha256']and v['verifierSourceSha256']==config['helpers']['suspensionVerifier']['sha256'],'SOURCE_JOIN');require(re.fullmatch('[a-f0-9]{32}',v['operation'])and set(v['otherNine'])==SERVICES-{'frontend'},'OPERATION');c=v['stop'];require(c['argv']==['stop','--time','60',v['frontend']['id']]and type(c['originalPid'])is int and c['originalPid']>0 and c['code']==0 and c['signal']is None and c['stdoutEof']is True and c['stderrEof']is True and c['spawnError']is None and c['streamError']is None and c['outputBoundExceeded']is False and c['interrupted']is False,'ORIGINAL_STOP');st=v['stopped'];require(st['status']=='exited'and st['running']is False and st['pid']==0 and st['exitCode']in(0,143)and st['oomKilled']is False and st['dead']is False and st['error']==''and isinstance(st['finishedAt'],str)and st['finishedAt']!=v['frontend']['startedAt'],'STOP_STATE');require(re.fullmatch('[a-f0-9]{64}',v['frontend']['id'])and re.fullmatch('sha256:[a-f0-9]{64}',v['frontend']['image'])and re.fullmatch('[a-f0-9]{64}',v['frontend']['configurationSha256']),'IDENTITY');
 if readback:
  ref=v['candidateReplacementReceipt'];candidate_raw=stable(native_file(ref['file']),16*1024*1024);require(sha(candidate_raw)==ref['sha256'],'CANDIDATE_PIN');candidate=json.loads(candidate_raw);require(candidate['pass']is True and candidate['phase']=='COMPLETE'and candidate['productionAdmission']is False and candidate['originalChildren']==dict(allOriginalChildrenClosed=True,interrupted=False),'CANDIDATE_NOT_COMPLETED');require(v['qualificationSlots']=={service:{key:candidate['actual'][service][key]for key in ('id','image','startedAt')}for service in ('backend-candidate','backend-retained')},'CANDIDATE_SLOTS')
  file=native_file(selection['file']);require(file.name=='stopped.json'and file.parent.name=='local-dev-frontend-suspension-'+v['operation'],'RECEIPT_PATH');require(stable(file)==raw,'RECEIPT_CHANGED');pending=stable(file.parent/'pending-restoration.json');require(sha(pending)==v['pendingSha256']and not(file.parent/'restored.json').exists()and not(file.parent/'restoring.json').exists(),'RESTORATION_PENDING');p=json.loads(pending);require(p['format']=='sabalan-local-dev-frontend-restoration-obligation/v1'and p['project']=='sabalanerp-local'and p['service']=='frontend'and p['frontend']==v['frontend']and p['operation']==v['operation'],'PENDING_JOIN');require(sha(stable(config['helpers']['suspensionOwner']['file']))==v['ownerSourceSha256']and sha(stable(config['helpers']['suspensionVerifier']['file']))==v['verifierSourceSha256'],'OWNER_SOURCE')
 return v
def validate_rows(rows,config,readback=True):
 v=validate_scope(config,readback);require(len(rows)==10 and {x.get('Service')for x in rows}==SERVICES and all(x.get('Project')=='sabalanerp-local'for x in rows),'TEN_ROWS');
 for row in rows:
  if row['Service']=='frontend':require(row.get('ID')==v['frontend']['id']and row.get('State')=='exited','STOPPED_ROW')
  else:require(row.get('State')=='running'and row.get('Health')=='healthy','OTHER_NINE')
 return v
def validate_inspected(actual,config,readback=True):
 v=validate_scope(config,readback);require(actual['Config']['Labels']['com.docker.compose.project']=='sabalanerp-local'and actual['Config']['Labels']['com.docker.compose.service']=='frontend','INSPECT_SCOPE');require(dict(id=actual['Id'],image=actual['Image'],startedAt=actual['State']['StartedAt'],configurationSha256=sha(canonical(dict(Config=actual['Config'],HostConfig=actual['HostConfig'],Mounts=actual['Mounts']))))==v['frontend'],'INSPECT_IDENTITY');s=actual['State'];require(s['Running']is False and s['Pid']==0 and s['Status']=='exited'and s['ExitCode']==v['stopped']['exitCode']and s['FinishedAt']==v['stopped']['finishedAt']and s['OOMKilled']is False and s['Dead']is False and s['Error']=='','INSPECT_STATE');return v
